input.command:
timeout 180 duckdb -c "
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
SELECT count(*) AS n_rows
FROM read_parquet('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet');
" 2>&1 | head -40

timeout 300 duckdb -c "
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
.mode line
-- q02: facilities schema + tier
SELECT 'FACILITIES COLUMNS' AS t;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 1;
" 2>&1 | head -80

timeout 300 duckdb -json -c "
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 1;
" 2>&1 | head -120

timeout 300 duckdb -json -c "
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
SELECT tier, count(*) AS n
FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet')
GROUP BY tier ORDER BY tier;
" 2>&1 | head -40

timeout 400 duckdb -json -c "
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
SELECT decode(value) AS geo
FROM parquet_kv_metadata('https://data.source.coop/wri-data-lab/trazofields/trazo3-fields/trazo3_brazil_goias_2024.parquet')
WHERE decode(key)='geo';
" 2>&1 | head -20

timeout 600 duckdb -json -c "
INSTALL httpfs; LOAD httpfs; INSTALL spatial; LOAD spatial;
SELECT count(*) AS n_rows, count(DISTINCT cod_imovel) AS n_distinct_ids
FROM read_parquet('https://data.source.coop/tristangruppwri/cadastral/brazil-car-area-imovel/brazil_car_area_imovel.parquet');
" 2>&1 | tail -5
